"""ARENA u09 的 10 道测验（沿用旧版题目，仅去掉解释里的位置引用）"""
from unitlib import Q
QUIZ = [
  Q('一个事件发生的概率是 1/8，它的信息量是多少比特？', ['1/8', '3', '8', '0'], 1, '$-\\log_2(1/8) = \\log_2 8 = 3$ 比特。'),
  Q('下面哪个分布的熵**最大**？', ['(1, 0, 0, 0)', '(0.7, 0.1, 0.1, 0.1)', '(0.5, 0.5, 0, 0)', '(0.25, 0.25, 0.25, 0.25)'], 3, '结果数相同时，均匀分布的熵最大（$\\log 4 = 2$ 比特）；(1,0,0,0) 完全确定，熵为 0。'),
  Q('一枚公平硬币的熵是多少比特？', ['1', '0.5', '2', '0'], 0, '$-(0.5\\log_2 0.5 + 0.5\\log_2 0.5) = 1$ 比特。'),
  Q('交叉熵 $H(P, Q)$ 和熵 $H(P)$ 的关系是？', ['$H(P, Q) \\le H(P)$', '两者总是相等', '$H(P, Q) \\ge H(P)$，当 $Q = P$ 时取等号', '$H(P, Q) = H(P) \\times H(Q)$'], 2, '$H(P, Q) = H(P) + D_{KL}(P\\|Q)$，而 KL 散度非负。用错误的分布去预测只会更意外。'),
  Q('关于 KL 散度 $D_{KL}(P\\|Q)$，下面哪个说法**错误**？', ['它总是大于等于 0', '它是对称的：$D_{KL}(P\\|Q) = D_{KL}(Q\\|P)$', '$P = Q$ 时它等于 0', '它等于 $H(P, Q) - H(P)$'], 1, 'KL 散度**不对称**，所以它不是真正意义上的距离。'),
  Q('为什么训练时「最小化交叉熵」等价于「最小化 KL 散度」？', ['因为数据分布 $P$ 固定，$H(P)$ 是常数', '因为交叉熵总是等于 0', '因为 KL 散度就是交叉熵', '因为 $P$ 和 $Q$ 总是相等'], 0, '$H(P,Q) = H(P) + D_{KL}(P\\|Q)$，训练只改 $Q$，$H(P)$ 不变，所以两者差一个常数。'),
  Q('下一个词的真实答案是 "cat"，模型给 "cat" 的概率是 0.25。这一步的交叉熵损失（自然对数）是？', ['0.25', '$-\\ln 0.75$', '$\\ln 0.25$', '$\\ln 4 \\approx 1.39$'], 3, '目标是独热分布，损失只剩 $-\\ln Q(\\text{cat}) = -\\ln 0.25 = \\ln 4$。$\\ln 0.25$ 少了负号，是个负数，而损失不可能为负。'),
  Q('词表大小为 $|V|$，模型对每个词都给出均匀概率 $1/|V|$，交叉熵损失是多少？', ['0', '$1/|V|$', '$\\log|V|$', '$|V|$'], 2, '$-\\log(1/|V|) = \\log|V|$。GPT-2 词表 50,257 个词，随机初始化时 loss 约为 10.8。'),
  Q('如果模型的预测分布 $Q$ 完全等于语言的真实分布 $P$，交叉熵会降到多少？', ['$H(P)$，即语言本身的熵', '0', '$\\log|V|$', '无穷大'], 0, '$Q = P$ 时 KL 散度为 0，交叉熵等于 $H(P)$。语言本身有不确定性，所以损失不会降到 0。'),
  Q('PyTorch 的 `F.cross_entropy` 默认用的对数是？', ['以 2 为底，单位是比特', '以 10 为底', '没有对数', '自然对数，单位是奈特'], 3, 'PyTorch 的损失函数用自然对数 $\\ln$。换算：1 奈特 ≈ 1.44 比特。'),
]
